-- Opening balances belong to the whole company, like the journal they post. Whoever keeps or
-- checks the books reads them; an owner or an accountant enters them. A member limited to some
-- branches has no part in them, as with every company-wide journal.
CREATE POLICY opening_entries_select ON public.opening_entries FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor')
    AND (SELECT app.tenant_branch_ids()) IS NULL
  );
