-- ── hand-written: opening balances post through the engine ──────────────────────────────────────
-- The three lists of what may post, replaced to add the opening entry. An owner or an
-- accountant posts it and reverses it. It may not touch the accounts that must agree with
-- records an opening entry does not bring (stock, goods in transit, goods received not
-- invoiced, cheques in hand, advances); receivables and payables it may, because each of its
-- lines there names the customer or the supplier.
CREATE OR REPLACE FUNCTION app.journal_source_roles(p_source_type text) RETURNS public.member_role[]
  LANGUAGE sql IMMUTABLE SET search_path = ''
  AS $$
    SELECT CASE p_source_type
      WHEN 'manual_journal' THEN ARRAY['owner', 'accountant']::public.member_role[]
      WHEN 'opening_balance' THEN ARRAY['owner', 'accountant']::public.member_role[]
    END
  $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.journal_source_reversal_roles(p_source_type text) RETURNS public.member_role[]
  LANGUAGE sql IMMUTABLE SET search_path = ''
  AS $$
    SELECT CASE p_source_type
      WHEN 'manual_journal' THEN ARRAY['owner', 'accountant']::public.member_role[]
      WHEN 'opening_balance' THEN ARRAY['owner', 'accountant']::public.member_role[]
    END
  $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.journal_source_blocked_controls(p_source_type text) RETURNS text[]
  LANGUAGE sql IMMUTABLE SET search_path = ''
  AS $$
    SELECT CASE p_source_type
      WHEN 'manual_journal' THEN ARRAY['ar', 'ap', 'inventory', 'customer_advances', 'supplier_advances', 'grni', 'goods_in_transit', 'cheques_in_hand']
      WHEN 'opening_balance' THEN ARRAY['inventory', 'customer_advances', 'supplier_advances', 'grni', 'goods_in_transit', 'cheques_in_hand']
      ELSE ARRAY[]::text[]
    END
  $$;
