-- ── hand-written: nothing is posted before the books opened here ────────────────────────────────
-- The engine's check of a journal's date (drizzle/0012_ledger.sql), with one rule more: once a
-- company's opening balances are posted, no journal may be dated before their date (SE015).
-- What happened before that day is already inside the opening balances; a journal for it would
-- count it twice. The opening journal and its reversal are dated on the opening date itself.
CREATE OR REPLACE FUNCTION app.require_open_period(p_tenant uuid, p_date date) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_locked timestamptz;
  v_opened date;
BEGIN
  SELECT p.locked_at INTO v_locked FROM public.fiscal_periods p
    WHERE p.tenant_id = p_tenant AND p.starts_on <= p_date AND p.ends_on >= p_date
    FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no fiscal period covers %', p_date USING ERRCODE = 'SE001';
  END IF;
  IF v_locked IS NOT NULL THEN
    RAISE EXCEPTION 'the fiscal period of % is locked', p_date USING ERRCODE = 'SE002';
  END IF;
  SELECT e.opening_date INTO v_opened FROM public.opening_entries e
    WHERE e.tenant_id = p_tenant AND e.status = 'posted';
  IF v_opened IS NOT NULL AND p_date < v_opened THEN
    RAISE EXCEPTION 'the books were opened on %; nothing is posted before that', v_opened USING ERRCODE = 'SE015';
  END IF;
END $$;
--> statement-breakpoint

-- ── hand-written: what may happen to an opening entry ───────────────────────────────────────────
-- A draft changes freely and can be thrown away. It becomes posted only in the transaction that
-- posted its journal through the engine, on its own date, under the poster's own name, with at
-- least one line, with every invoice and bill dated before the opening date, with nothing in
-- the books from before that date, and only if that journal says what the entry's lines say: every account at its balance, receivables customer by customer,
-- payables supplier by supplier (the line to opening balance equity aside, which is whatever
-- those differ by). A posted one changes once more, to reversed, in the transaction that posted
-- its reversal. Nothing else about a posted or reversed entry ever changes, and it is never
-- removed.
--
-- The functions run with the table owner's rights so that they can read the ledger, so they
-- first refuse any row outside the caller's own company, asked afresh for every row. Only a
-- session signed in as postgres itself (a migration, or the removal of a synthetic test
-- company) is not held to these rules. The times on a row are the database's own.
CREATE FUNCTION app.check_opening_entry() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_receivables uuid;
  v_payables uuid;
  v_equity uuid;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'posted opening balances are never removed; reverse them instead' USING ERRCODE = 'SE041';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' AND NEW.status = 'posted' THEN
    IF NEW.opening_date <> OLD.opening_date THEN
      RAISE EXCEPTION 'opening balances are posted as they stand' USING ERRCODE = 'SE043';
    END IF;
    IF NEW.posted_by IS DISTINCT FROM app.current_user_id() THEN
      RAISE EXCEPTION 'opening balances are posted under the name of whoever posts them' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.opening_balances b WHERE b.tenant_id = NEW.tenant_id AND b.opening_entry_id = NEW.id) THEN
      RAISE EXCEPTION 'an opening entry with no lines is not posted' USING ERRCODE = 'SE043';
    END IF;
    -- Every invoice and bill brought in was written before the books opened here.
    IF EXISTS (
      SELECT 1 FROM public.opening_balances b
      WHERE b.tenant_id = NEW.tenant_id AND b.opening_entry_id = NEW.id AND b.document_date >= NEW.opening_date
    ) THEN
      RAISE EXCEPTION 'an invoice or bill at opening is dated before the opening date' USING ERRCODE = 'SE043';
    END IF;
    -- Nothing is in the books from before the opening date: it would be counted twice.
    IF EXISTS (
      SELECT 1 FROM public.journals j
      WHERE j.tenant_id = NEW.tenant_id AND j.journal_date < NEW.opening_date
        -- Earlier opening balances that were reversed cancel out and do not count.
        AND j.source_type <> 'opening_balance'
        AND NOT (j.source_type = 'reversal' AND EXISTS (
          SELECT 1 FROM public.journals o
          WHERE o.tenant_id = j.tenant_id AND o.id = j.reverses_journal_id AND o.source_type = 'opening_balance'))
    ) THEN
      RAISE EXCEPTION 'the books already hold journals dated before the opening date' USING ERRCODE = 'SE045';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.journals j
      WHERE j.tenant_id = NEW.tenant_id AND j.id = NEW.journal_id
        AND j.source_type = 'opening_balance' AND j.source_id = NEW.id
        AND j.posted_txid = txid_current()
        AND j.journal_date = NEW.opening_date
    ) THEN
      RAISE EXCEPTION 'opening balances are posted only with the journal the engine posted for them' USING ERRCODE = 'SE043';
    END IF;
    SELECT a.id INTO v_receivables FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.is_control AND NOT a.is_group AND a.control_type = 'ar';
    SELECT a.id INTO v_payables FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.is_control AND NOT a.is_group AND a.control_type = 'ap';
    SELECT a.id INTO v_equity FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.is_control AND NOT a.is_group AND a.control_type = 'opening_equity';
    IF EXISTS (
      WITH entered AS (
        SELECT CASE b.kind WHEN 'account' THEN b.account_id WHEN 'receivable' THEN v_receivables ELSE v_payables END AS account_id,
               b.customer_id, b.supplier_id, sum(b.debit) AS debit, sum(b.credit) AS credit
          FROM public.opening_balances b
          WHERE b.tenant_id = NEW.tenant_id AND b.opening_entry_id = NEW.id
          GROUP BY 1, 2, 3
      ), posted AS (
        SELECT l.account_id, l.customer_id, l.supplier_id, sum(l.debit) AS debit, sum(l.credit) AS credit
          FROM public.journal_lines l
          WHERE l.tenant_id = NEW.tenant_id AND l.journal_id = NEW.journal_id AND l.account_id IS DISTINCT FROM v_equity
          GROUP BY 1, 2, 3
      )
      (SELECT * FROM entered EXCEPT SELECT * FROM posted)
      UNION ALL
      (SELECT * FROM posted EXCEPT SELECT * FROM entered)
    ) THEN
      RAISE EXCEPTION 'the journal posted is not what the opening entry''s lines say' USING ERRCODE = 'SE043';
    END IF;
    NEW.posted_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'posted' AND NEW.status = 'reversed' THEN
    IF NEW.opening_date <> OLD.opening_date OR NEW.journal_id <> OLD.journal_id OR NEW.posted_at <> OLD.posted_at OR NEW.posted_by <> OLD.posted_by THEN
      RAISE EXCEPTION 'posted opening balances are never changed; reverse them instead' USING ERRCODE = 'SE041';
    END IF;
    IF NEW.reversed_by IS DISTINCT FROM app.current_user_id() THEN
      RAISE EXCEPTION 'opening balances are reversed under the name of whoever reverses them' USING ERRCODE = 'insufficient_privilege';
    END IF;
    -- The reversal carries the opening date itself, so that no date in between ever shows the
    -- opening balances twice once the corrected ones are posted.
    IF NOT EXISTS (
      SELECT 1 FROM public.journals j
      WHERE j.tenant_id = NEW.tenant_id AND j.id = NEW.reversal_journal_id
        AND j.reverses_journal_id = OLD.journal_id
        AND j.posted_txid = txid_current()
        AND j.journal_date = OLD.opening_date
    ) THEN
      RAISE EXCEPTION 'opening balances are reversed only with the reversal the engine posted for them, on the opening date' USING ERRCODE = 'SE043';
    END IF;
    NEW.reversed_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' THEN
    RAISE EXCEPTION 'a draft is posted before it can be reversed' USING ERRCODE = 'SE043';
  END IF;
  RAISE EXCEPTION 'posted opening balances are never changed; reverse them instead' USING ERRCODE = 'SE041';
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_opening_entry() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER opening_entries_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.opening_entries
  FOR EACH ROW EXECUTE FUNCTION app.check_opening_entry();
--> statement-breakpoint
