-- Lines are written and removed only while their entry is a draft. The entry's row is held
-- until the transaction ends, so a line cannot slip in while the entry is being posted.
CREATE FUNCTION app.check_opening_balance() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid;
  v_entry uuid;
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    v_entry := OLD.opening_entry_id;
  ELSE
    v_tenant := NEW.tenant_id;
    v_entry := NEW.opening_entry_id;
  END IF;
  IF session_user <> 'postgres' THEN
    IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    SELECT e.status INTO v_status FROM public.opening_entries e
      WHERE e.tenant_id = v_tenant AND e.id = v_entry
      FOR SHARE;
    IF FOUND AND v_status <> 'draft' THEN
      RAISE EXCEPTION 'posted opening balances are never changed; reverse them instead' USING ERRCODE = 'SE041';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.created_at := now();
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_opening_balance() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER opening_balances_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.opening_balances
  FOR EACH ROW EXECUTE FUNCTION app.check_opening_balance();
--> statement-breakpoint
ALTER TABLE public.opening_balances ENABLE ALWAYS TRIGGER opening_balances_check;
